const planOut =
  $('Supabase V3 - Current Enrichment Plan').first().json || {};
const qaOut =
  $('Supabase V3 - QA Baseline').first().json || {};

function rowsFromBroker(out, rpc) {
  if (out.broker !== 'supabase') {
    throw new Error(`GTM06 FINAL expected Supabase broker for ${rpc}`);
  }
  if (out.broker_version !== 'SB-BROKER-V3.0.0') {
    throw new Error(
      `GTM06 FINAL expected SB-BROKER-V3.0.0, got ${out.broker_version}`
    );
  }
  if (out.rpc_name !== rpc) {
    throw new Error(
      `GTM06 FINAL expected ${rpc}, got ${out.rpc_name}`
    );
  }
  return Array.isArray(out.response) ? out.response : [];
}

const plan = rowsFromBroker(
  planOut,
  'gtm_contact_email_enrichment_plan_v1'
);

const qaRows = rowsFromBroker(
  qaOut,
  'gtm_project01_qa_report_v1'
);

if (qaRows.length !== 1) {
  throw new Error(
    `GTM06 FINAL expected exactly one QA report, got ${qaRows.length}`
  );
}

const qa = qaRows[0];

if (qa.state !== 'PRE_SEND_CONTROLLED' || qa.all_checks_pass !== true) {
  throw new Error(
    `GTM06 FINAL baseline QA is not green: ${qa.state}`
  );
}

// Current frozen pilot has seven verified canonical emails,
// therefore the enrichment candidate plan must now be empty.
if (plan.length !== 0) {
  const summary = plan
    .map(x =>
      `${x.candidate_priority_rank}:${x.full_name} [${x.persona}]`
    )
    .join(' | ');

  throw new Error(
    `GTM06 FINAL expected 0 remaining enrichment candidates in the frozen pilot, got ${plan.length}: ${summary}`
  );
}

return [{
  json: {
    gtm06_final_dry_run_completed: true,

    enrichment_contract_version: 'CE-V1.0.0',
    provider: 'prospeo',
    endpoint: '/enrich-person',

    current_remaining_candidates: plan.length,
    current_pilot_fully_enriched: true,

    only_verified_email: true,
    mobile_enrichment_allowed: false,
    serialized_single_contact_execution: true,
    delay_seconds_before_provider_call: 2,

    provider_http_call_performed: false,
    provider_credits_spent: 0,
    database_mutation_performed: false,

    retry_policy: {
      http_429: 'retryable_failed',
      http_5xx: 'retryable_failed',
      internal_error: 'retryable_failed',
      retry_delay_minutes: 60,
      attempt_count_is_never_reset: true
    },

    current_qa_state: qa.state,
    current_qa_all_checks_pass: qa.all_checks_pass,

    supabase_broker_v3_passed: true,
    supabase_workflow_id: 'SUPABASE_BROKER_V3_WORKFLOW_ID',

    live_entrypoint_configured: true,
    live_entrypoint_requires_exact_confirmation:
      'EXECUTE_PROSPEO_ENRICH',

    gtm06_final_dry_run_all_checks_pass: true,

    next_action:
      'Keep enrichment live execution disabled for the frozen pilot. Use the controlled entrypoint only when GTM05 creates new verified-email enrichment candidates.'
  }
}];

const input = $input.first().json || {};

const executionMode =
  String(input.execution_mode || 'fresh').trim().toLowerCase();

const rank = Number(input.candidate_priority_rank);
const runMode =
  String(input.run_mode || 'pilot').trim().toLowerCase();

const maxContacts = Number(input.max_contacts ?? 1);
const maxCreditBudget = Number(input.max_credit_budget ?? 1);

const confirmation =
  String(input.execute_provider_call || '').trim();

if (!['fresh','retry'].includes(executionMode)) {
  throw new Error(
    `GTM06 FINAL execution_mode must be fresh or retry, got ${executionMode}`
  );
}

if (!Number.isInteger(rank) || rank < 1) {
  throw new Error(
    'GTM06 FINAL candidate_priority_rank must be an integer >= 1'
  );
}

if (!['pilot','full','replay'].includes(runMode)) {
  throw new Error(`GTM06 FINAL unsupported run_mode: ${runMode}`);
}

if (!Number.isInteger(maxContacts) || maxContacts < 1 || maxContacts > 25) {
  throw new Error(
    'GTM06 FINAL max_contacts must be an integer from 1 to 25'
  );
}

if (
  !Number.isInteger(maxCreditBudget) ||
  maxCreditBudget < 1 ||
  maxCreditBudget > 25
) {
  throw new Error(
    'GTM06 FINAL max_credit_budget must be an integer from 1 to 25'
  );
}

if (maxCreditBudget < maxContacts) {
  throw new Error(
    'GTM06 FINAL max_credit_budget must be >= max_contacts'
  );
}

if (executionMode === 'fresh' && rank > maxContacts) {
  throw new Error(
    `GTM06 FINAL fresh execution rank ${rank} exceeds max_contacts ${maxContacts}. Seed enough tasks to include the requested rank.`
  );
}

if (confirmation !== 'EXECUTE_PROSPEO_ENRICH') {
  throw new Error(
    'GTM06 FINAL provider call blocked. execute_provider_call must equal EXECUTE_PROSPEO_ENRICH exactly.'
  );
}

return [{
  json: {
    execution_mode: executionMode,
    candidate_priority_rank: rank,
    run_mode: runMode,
    max_contacts: maxContacts,
    max_credit_budget: maxCreditBudget,

    provider_name: 'prospeo',
    provider_contract_version: 'CE-V1.0.0',

    only_verified_email: true,
    enrich_mobile: false,

    live_provider_call_confirmed: true
  }
}];

const cfg =
  $('Validate Controlled Enrichment Input').first().json;

const out = $input.first().json || {};

if (
  out.broker !== 'supabase' ||
  out.broker_version !== 'SB-BROKER-V3.0.0' ||
  out.rpc_name !== 'gtm_seed_contact_email_enrichment_run_v1'
) {
  throw new Error(
    'GTM06 FINAL seed did not return through Supabase Broker V3'
  );
}

const rows = Array.isArray(out.response) ? out.response : [];

if (rows.length !== 1 || !rows[0]?.run_id) {
  throw new Error(
    `GTM06 FINAL expected one canonical enrichment run, got ${rows.length}`
  );
}

const seed = rows[0];

if (Number(seed.planned_task_count) < cfg.candidate_priority_rank) {
  throw new Error(
    `GTM06 FINAL requested rank ${cfg.candidate_priority_rank} but run contains only ${seed.planned_task_count} planned task(s)`
  );
}

return [{
  json: {
    ...cfg,
    enrichment_run_id: seed.run_id,
    enrichment_run_key: seed.run_key,
    eligible_contact_count: Number(seed.eligible_contact_count),
    planned_task_count: Number(seed.planned_task_count),
    max_credit_budget: Number(seed.max_credit_budget)
  }
}];

const cfg =
  $('Validate Controlled Enrichment Input').first().json;

const out = $input.first().json || {};

if (
  out.broker !== 'supabase' ||
  out.broker_version !== 'SB-BROKER-V3.0.0' ||
  out.rpc_name !== 'gtm_claim_contact_email_enrichment_v1'
) {
  throw new Error(
    'GTM06 FINAL claim did not return through Supabase Broker V3'
  );
}

const rows = Array.isArray(out.response) ? out.response : [];

if (rows.length !== 1) {
  throw new Error(
    `GTM06 FINAL expected exactly one claimed enrichment task, got ${rows.length}`
  );
}

const claim = rows[0];

const required = [
  'task_key',
  'run_id',
  'contact_id',
  'candidate_priority_rank',
  'full_name',
  'provider_contact_id',
  'attempt_count',
  'estimated_credit_cost'
];

for (const key of required) {
  if (
    claim[key] === undefined ||
    claim[key] === null ||
    claim[key] === ''
  ) {
    throw new Error(
      `GTM06 FINAL claimed task missing ${key}`
    );
  }
}

if (
  Number(claim.candidate_priority_rank) !==
  cfg.candidate_priority_rank
) {
  throw new Error(
    `GTM06 FINAL claimed rank ${claim.candidate_priority_rank}; expected ${cfg.candidate_priority_rank}`
  );
}

if (Number(claim.attempt_count) < 1) {
  throw new Error(
    `GTM06 FINAL invalid attempt_count after claim: ${claim.attempt_count}`
  );
}

if (Number(claim.estimated_credit_cost) !== 1) {
  throw new Error(
    `GTM06 FINAL expected one-credit estimate, got ${claim.estimated_credit_cost}`
  );
}

return [{
  json: {
    ...claim,

    execution_mode: cfg.execution_mode,

    prospeo_request_body: {
      only_verified_email: true,
      enrich_mobile: false,
      data: {
        person_id: claim.provider_contact_id
      }
    },

    provider_call_allowed: true,
    max_credit_exposure_for_this_execution: 1,
    mobile_enrichment_allowed: false
  }
}];

const claim =
  $('Build Verified Email Request').first().json;

const response = $input.first().json || {};

const safeStringify = value => {
  try {
    return JSON.stringify(value);
  } catch (_) {
    return String(value);
  }
};

let providerPayload = null;

if (
  response?.error === false &&
  response?.person
) {
  providerPayload = response;
} else {
  const candidates = [
    response?.error?.message,
    response?.message,
    response?.body
  ].filter(v =>
    typeof v === 'string' &&
    v.trim()
  );

  for (const text of candidates) {
    const first = text.indexOf('{');
    const last = text.lastIndexOf('}');

    if (first >= 0 && last > first) {
      const inner =
        text.slice(first, last + 1).replace(/\\"/g, '"');

      try {
        const parsed = JSON.parse(inner);

        if (
          parsed &&
          typeof parsed === 'object'
        ) {
          providerPayload = parsed;
          break;
        }
      } catch (_) {}
    }
  }
}

const statusCandidate = [
  response?.error?.status,
  response?.statusCode,
  response?.status
].find(v =>
  Number.isInteger(Number(v))
);

let httpStatus =
  providerPayload?.error === false
    ? 200
    : statusCandidate !== undefined
      ? Number(statusCandidate)
      : null;

let outcome;
let returnedProviderContactId = null;
let email = null;
let emailStatus = null;
let freeEnrichment = null;
let errorCode = null;
let errorMessage = null;
let nextRetryAt = null;

if (
  providerPayload?.error === false &&
  providerPayload?.person
) {
  const person = providerPayload.person;
  const emailObj = person.email || {};

  returnedProviderContactId =
    person.person_id || null;

  email =
    emailObj.email || null;

  emailStatus =
    emailObj.status || null;

  freeEnrichment =
    Boolean(providerPayload.free_enrichment);

  const identityMatches =
    returnedProviderContactId ===
    claim.provider_contact_id;

  const verifiedEmail =
    emailStatus === 'VERIFIED' &&
    emailObj.revealed === true &&
    typeof email === 'string' &&
    email.includes('@');

  const mobileWasUnexpectedlyRevealed =
    providerPayload?.person?.mobile?.revealed === true;

  if (
    identityMatches &&
    verifiedEmail &&
    !mobileWasUnexpectedlyRevealed
  ) {
    outcome = 'succeeded';
  } else {
    outcome = 'permanent_failed';

    if (!identityMatches) {
      errorCode =
        'PROVIDER_IDENTITY_MISMATCH';

      errorMessage =
        `Prospeo returned person_id ${returnedProviderContactId}; expected ${claim.provider_contact_id}`;
    } else if (mobileWasUnexpectedlyRevealed) {
      errorCode =
        'UNEXPECTED_MOBILE_REVEAL';

      errorMessage =
        'Prospeo unexpectedly revealed mobile data even though enrich_mobile=false.';
    } else {
      errorCode =
        'UNEXPECTED_ENRICHMENT_PAYLOAD';

      errorMessage =
        'Prospeo success response did not contain a revealed VERIFIED email.';
    }
  }
} else {
  const providerCode =
    providerPayload?.error_code || null;

  if (httpStatus === 429) {
    errorCode = 'RATE_LIMITED';
  } else {
    errorCode = String(
      providerCode ||
      response?.error?.code ||
      response?.code ||
      'PROSPEO_UNPARSED_ERROR'
    );
  }

  errorMessage = String(
    providerPayload?.message ||
    response?.error?.message ||
    response?.message ||
    (
      httpStatus === 429
        ? 'Prospeo enrichment rate limit exceeded.'
        : 'Prospeo enrichment returned an unparsed error'
    )
  ).slice(0, 2000);

  if (providerCode === 'NO_MATCH') {
    outcome = 'no_match';

    if (httpStatus === null) {
      httpStatus = 400;
    }
  } else if (
    httpStatus === 429 ||
    (
      httpStatus !== null &&
      httpStatus >= 500
    ) ||
    providerCode === 'INTERNAL_ERROR'
  ) {
    outcome = 'retryable_failed';

    nextRetryAt =
      new Date(
        Date.now() + 60 * 60 * 1000
      ).toISOString();
  } else {
    outcome = 'permanent_failed';
  }
}

return [{
  json: {
    task_key: claim.task_key,
    run_id: claim.run_id,
    contact_id: claim.contact_id,
    candidate_priority_rank:
      Number(claim.candidate_priority_rank),

    full_name: claim.full_name,
    job_title: claim.job_title,
    persona: claim.persona,

    claimed_provider_contact_id:
      claim.provider_contact_id,

    attempt_count_after_claim:
      Number(claim.attempt_count),

    outcome,

    returned_provider_contact_id:
      returnedProviderContactId,

    verified_email: email,
    email_status: emailStatus,
    free_enrichment: freeEnrichment,

    http_status: httpStatus,
    error_code: errorCode,
    error_message: errorMessage,
    next_retry_at: nextRetryAt,

    provider_call_performed: true,

    response_metadata: {
      stage: 'GTM06_FINAL',
      endpoint: '/enrich-person',

      serialized_single_contact_execution: true,
      rate_guard_seconds: 2,

      only_verified_email: true,
      enrich_mobile: false,

      claimed_provider_contact_id:
        claim.provider_contact_id,

      returned_provider_contact_id:
        returnedProviderContactId,

      free_enrichment: freeEnrichment,
      email_status: emailStatus,

      email_revealed:
        providerPayload?.person?.email?.revealed === true,

      mobile_revealed:
        providerPayload?.person?.mobile?.revealed === true,

      provider_error_code:
        providerPayload?.error_code || null,

      raw_error_preview:
        safeStringify(
          response?.error || null
        ).slice(0, 1000)
    }
  }
}];

const normalized =
  $('Normalize Enrichment - Preserve Attempt').first().json;

const finalOut =
  $('Supabase V3 - Finalize Enrichment Atomically').first().json || {};

const remainingOut =
  $input.first().json || {};

if (
  finalOut.broker !== 'supabase' ||
  finalOut.broker_version !== 'SB-BROKER-V3.0.0' ||
  finalOut.rpc_name !== 'gtm_finalize_contact_email_enrichment_v1'
) {
  throw new Error(
    'GTM06 FINAL atomic finalize did not return through Supabase Broker V3'
  );
}

const finals =
  Array.isArray(finalOut.response)
    ? finalOut.response
    : [];

if (finals.length !== 1) {
  throw new Error(
    `GTM06 FINAL expected one finalized task row, got ${finals.length}`
  );
}

const final = finals[0];

if (
  remainingOut.broker !== 'supabase' ||
  remainingOut.broker_version !== 'SB-BROKER-V3.0.0' ||
  remainingOut.rpc_name !== 'gtm_contact_email_enrichment_plan_v1'
) {
  throw new Error(
    'GTM06 FINAL remaining plan did not return through Supabase Broker V3'
  );
}

const remaining =
  Array.isArray(remainingOut.response)
    ? remainingOut.response
    : [];

const terminal = new Set([
  'succeeded',
  'no_match',
  'permanent_failed',
  'retryable_failed'
]);

const taskStatus =
  final.task_status ||
  final.status ||
  normalized.outcome;

if (!terminal.has(taskStatus)) {
  throw new Error(
    `GTM06 FINAL unexpected finalized status: ${taskStatus}`
  );
}

return [{
  json: {
    gtm06_controlled_enrichment_completed: true,

    provider: 'prospeo',
    enrichment_contract_version: 'CE-V1.0.0',

    full_name: normalized.full_name,
    job_title: normalized.job_title,
    persona: normalized.persona,

    provider_outcome: normalized.outcome,
    provider_http_status: normalized.http_status,
    provider_error_code: normalized.error_code,

    task_status: taskStatus,

    attempt_count:
      final.attempt_count ??
      normalized.attempt_count_after_claim,

    actual_credit_cost:
      final.actual_credit_cost ?? null,

    run_status:
      final.run_status ?? null,

    canonical_contact_id:
      final.contact_id ??
      normalized.contact_id,

    verified_email:
      final.canonical_email ??
      normalized.verified_email ??
      null,

    canonical_email_status:
      final.canonical_email_status ?? null,

    email_alias_present:
      Boolean(final.email_alias_present),

    free_enrichment:
      normalized.free_enrichment,

    mobile_enrichment_requested: false,

    provider_call_performed: true,

    remaining_candidate_count:
      remaining.length,

    remaining_candidate_summary:
      remaining
        .sort(
          (a,b) =>
            Number(a.candidate_priority_rank) -
            Number(b.candidate_priority_rank)
        )
        .map(
          x =>
            `${x.candidate_priority_rank}:${x.full_name} [${x.persona}]`
        )
        .join(' | '),

    next_retry_at:
      normalized.next_retry_at,

    error:
      normalized.error_message,

    next_action:
      taskStatus === 'retryable_failed'
        ? 'Do not reset the attempt. Wait until next_retry_at, then call this workflow with execution_mode=retry and the stored task rank.'
        : remaining.length > 0
          ? 'Process the next enrichment task serially. Do not run parallel Prospeo enrichment calls.'
          : 'Enrichment is complete. Re-run GTM10 Reporting & QA.'
  }
}];
